cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Check for any pending/cart-like orders
const pending = db.prepare(\"SELECT * FROM orders WHERE customer_id = ? AND (status = 'pending' OR status LIKE '%cart%' OR status LIKE '%pending%')\").all('user_fbab7801');
console.log('Pending/cart orders:', JSON.stringify(pending, null, 2));

// Check all statuses
const statuses = db.prepare(\"SELECT order_id, status, source_skill FROM orders WHERE customer_id = ?\").all('user_fbab7801');
console.log('\nAll order statuses:', JSON.stringify(statuses, null, 2));

// Check if there's a separate cart table
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('\nAll tables:', tables.map(t => t.name));

// Check for cart-related tables
const cartTables = tables.filter(t => t.name.toLowerCase().includes('cart'));
console.log('Cart tables:', cartTables);
db.close();
"

